import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BAQ5ZYJQ.js";const g=JSON.parse('{"title":"Fast, and nothing lost: agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":1794577911000}'),i={name:"guide/agents.md"};function o(h,e,r,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="fast-and-nothing-lost-agents" tabindex="-1">Fast, and nothing lost: agents <a class="header-anchor" href="#fast-and-nothing-lost-agents" aria-label="Permalink to &quot;Fast, and nothing lost: agents&quot;">​</a></h1><p>A command used to pay for everything again each time: an ssh login, a shell that reads its rc file, an <code>srun</code> in the queue, a container entered, a Python that imports torch. Now errand pays once. The first command leaves small processes behind (<strong>agents</strong>), and the next commands go through them.</p><table tabindex="0"><thead><tr><th></th><th>before</th><th>with agents</th></tr></thead><tbody><tr><td>a run on a machine over ssh</td><td>4–8 s</td><td>0.9–1.8 s</td></tr><tr><td>a run on a cluster, allocation held warm</td><td>the queue&#39;s minutes</td><td>about 1 s</td></tr><tr><td>a session that imports torch (CUDA), with <code>Preload</code></td><td>2.9 s</td><td>1.5 s</td></tr></tbody></table><p>There is nothing to declare: agents are the default on a terminal. They stop on their own when nothing uses them, and a closed laptop does not take the work with it.</p><h2 id="what-stays-and-where" tabindex="-1">What stays, and where <a class="header-anchor" href="#what-stays-and-where" aria-label="Permalink to &quot;What stays, and where&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  here                          the machine Ssh leads to             the end of the stack</span></span>
<span class="line"><span>  ────                          ────────────────────────             ────────────────────</span></span>
<span class="line"><span>  errand ── hub ── one ssh ──── host agent ── the layers, once ───── environment agent ── sessions</span></span>
<span class="line"><span>  errand ──┘                    (rsync, setup, probes)               (micromamba, container, …)</span></span></code></pre></div><ul><li><strong>The hub</strong> is one process here, per user. It keeps the streams to the agents open between commands, and several commands share them. The first command to want an agent pays for reaching it; the next ones do not.</li><li><strong>A host agent</strong> runs on each machine errand reaches. It started through one ssh, and everything goes through it: the rsyncs, which use it as their remote shell, the checks and builds of <code>setup</code>, the probes. Nothing logs in again.</li><li><strong>An environment agent</strong> runs past the layers, with the environment&#39;s own interpreter: inside the micromamba environment, the module, the container, the allocation. The layers are entered once, not once per command. It collects the entries and runs them.</li></ul><p>errand itself needs nothing installed over there. Its sources travel, and it finds a Python 3.8 or later to start on, or makes one for itself. → <a href="./layers/ssh#nothing-to-install-over-there">Nothing to install over there</a></p><h2 id="warm-imports-preload" tabindex="-1">Warm imports: <code>Preload</code> <a class="header-anchor" href="#warm-imports-preload" aria-label="Permalink to &quot;Warm imports: \`Preload\`&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.envs[ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errand.Env( [ errand.Ssh( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gpu-box&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                     errand.Micromamba( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;torch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                                     errand.Preload( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;torch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) ] )</span></span></code></pre></div><p>With the <a href="./layers/preload"><code>Preload</code></a> layer at the end of a stack, a session does not start a new Python. The environment agent keeps a process beside it that has already imported torch, and each session is a fork of that process. The project&#39;s own modules are always read again. Without the layer, every session is a Python started anew: you choose.</p><h2 id="held-warm-for-a-while" tabindex="-1">Held warm, for a while <a class="header-anchor" href="#held-warm-for-a-while" aria-label="Permalink to &quot;Held warm, for a while&quot;">​</a></h2><p>Each layer that costs something to start says how long it stays up once nobody uses it:</p><table tabindex="0"><thead><tr><th>what</th><th>stays up</th><th>declared by</th></tr></thead><tbody><tr><td>the hub, a host agent, an environment agent</td><td>15 minutes with nothing to do</td><td><code>ERRAND_HUB_KEEP_ALIVE</code> for the hub (seconds)</td></tr><tr><td>a Slurm allocation</td><td><code>keep_alive</code>, if given; otherwise one job per command</td><td><a href="./layers/slurm#held-warm-keep-alive"><code>Slurm( keep_alive = &quot;30m&quot; )</code></a></td></tr><tr><td>a Windows virtual machine</td><td>5 minutes</td><td><a href="./layers/windows#with-a-python-errand-runs-in-it"><code>Windows( keep = &quot;5m&quot; )</code></a></td></tr></tbody></table><p>&quot;Nothing to do&quot; means no request and nothing running. A connection held open does not count, which is what lets the chain come down from the far end. When the environment agent has had nothing to do for its time, it goes. The node agent above it then has nothing to do either, so the Slurm job ends and the allocation is released. The same happens with a virtual machine, and finally with the hub.</p><h2 id="giving-way" tabindex="-1">Giving way <a class="header-anchor" href="#giving-way" aria-label="Permalink to &quot;Giving way&quot;">​</a></h2><p>Something only kept warm is a cost to others while it waits. A virtual machine nobody uses holds cores and memory, and a process that imported torch holds memory too. They hold their claim in the <a href="./machine">machine&#39;s queue</a> as one that <strong>gives way</strong>. A command that needs the room asks for it, and gets it without waiting for the end of a <code>keep</code>: the machine stops, the process goes. While it waits, the command says what it waits for (&quot;…, kept warm, to make room&quot;), and <code>errand queue</code> marks those claims as kept warm.</p><p>A Slurm allocation held warm is never stretched to fit. A command runs in it only if it fits: its ranks within the allocation&#39;s tasks, its cores and cards per task within those declared, its <code>--time</code> within what the job has left. Otherwise the command gets a job of its own, sized for it. If nothing runs in the warm allocation, it is given back first, since it may hold the very nodes. No <code>srun</code> ever asks for more than was allocated. On a shared cluster, a short <code>keep_alive</code> is the polite choice.</p><h2 id="close-the-laptop" tabindex="-1">Close the laptop <a class="header-anchor" href="#close-the-laptop" aria-label="Permalink to &quot;Close the laptop&quot;">​</a></h2><p>What the agents start writes its output to disk where it runs, so a closed laptop or a dropped network loses nothing. The work goes on. <code>errand attach</code> follows it again: it shows the output from the start, waits for the end, and brings the results back.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bench/**::*&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # the laptop closes halfway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # later: the rest, the report, the results here</span></span></code></pre></div><h2 id="ctrl-c-means-stop" tabindex="-1">Ctrl-C means stop <a class="header-anchor" href="#ctrl-c-means-stop" aria-label="Permalink to &quot;Ctrl-C means stop&quot;">​</a></h2><p>Ctrl-C reaches the work wherever it runs, through every layer: over ssh, in a container, in an allocation, in a Windows guest. The work gets an interrupt first, as at a terminal. If it is still there after 2 seconds it is told to terminate, and after 5 seconds it is killed. errand then exits with code 130. A Python that catches <code>KeyboardInterrupt</code> and goes on does not keep errand waiting.</p><h2 id="a-real-terminal" tabindex="-1">A real terminal <a class="header-anchor" href="#a-real-terminal" aria-label="Permalink to &quot;A real terminal&quot;">​</a></h2><p><code>errand shell</code> gets a real terminal over there: a pty on Linux and macOS, a pseudo-console on Windows. Colours, line editing, full-screen programs, Ctrl-C as a key, and the window&#39;s size, followed as it changes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a shell in the allocation, the container, the environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> win</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # cmd.exe in the Windows guest, as at its console</span></span></code></pre></div><h2 id="leaving-nothing-behind" tabindex="-1">Leaving nothing behind <a class="header-anchor" href="#leaving-nothing-behind" aria-label="Permalink to &quot;Leaving nothing behind&quot;">​</a></h2><p>What errand keeps per user, here and over there, under <code>~/.cache/errand</code>, is only what is live: sockets, locks, pids, and a word per running command saying where its output goes. What piles up is the project&#39;s, in its <code>errand-outputs/</code> (over there, in the project&#39;s copy):</p><table tabindex="0"><thead><tr><th>what</th><th>where</th><th>until</th></tr></thead><tbody><tr><td>a command&#39;s output, kept for <code>errand attach</code></td><td><code>errand-outputs/state/procs/</code></td><td>it is brought back</td></tr><tr><td>run records</td><td><code>errand-outputs/runs/</code></td><td>you remove them</td></tr><tr><td>Windows images</td><td><code>errand-outputs/builds/windows/</code></td><td>a newer one is ready</td></tr></tbody></table><p>Agents and the hub stop when they have had nothing to do for their time, and take their sockets with them. A hub started from sources that have since changed also takes its directory with it. Errand&#39;s directories are named after its sources, so an edit to errand means new ones. When an agent or a hub starts, it removes the directories beside its own that nobody serves any more: untouched for an hour, and with a lock that no process holds. A Slurm allocation held warm takes its directory with it when the job ends; a virtual machine nobody used for a day leaves nothing here. What stays in <code>~/.cache/errand</code> for good is errand&#39;s own: its sources, and the Python it made for itself where the machine had none. <a href="./storage">Where errand writes</a> says how to put all of it elsewhere.</p><h2 id="what-is-up-and-stopping-it" tabindex="-1">What is up, and stopping it <a class="header-anchor" href="#what-is-up-and-stopping-it" aria-label="Permalink to &quot;What is up, and stopping it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the hub, and each agent it keeps a stream to</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # those whose name holds &quot;gpu&quot; go now</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # all of them, and the hub</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  hub  pid 79636  up 3 s   ~/.cache/errand/hub-c81a3d1d455a</span></span>
<span class="line"><span>    lmo                              last used 0 s ago, 1 open; kept 15 min unused</span></span>
<span class="line"><span>    lmo:env-c81a3d1d455a-32772dfcfc  last used 0 s ago; kept 15 min unused</span></span></code></pre></div><p>Stopping goes from the far end: an environment before the machine or the allocation it runs in. An allocation held warm goes with its agent, and the job ends. An agent with something running is left alone, and says so; <code>--force</code> stops it anyway.</p><p><code>errand status</code> starts with the commands left running when their connection was lost. For each, the agent says whether the work is still running or has finished and waits to be brought back with <code>errand attach</code>.</p><h2 id="when-you-want-it-otherwise" tabindex="-1">When you want it otherwise <a class="header-anchor" href="#when-you-want-it-otherwise" aria-label="Permalink to &quot;When you want it otherwise&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>ERRAND_AGENT</code></th><th></th></tr></thead><tbody><tr><td><code>hub</code></td><td>through the hub. The default on a terminal</td></tr><tr><td><code>direct</code></td><td>a connection owned by the command, closed with it. The default without a terminal (cron, CI)</td></tr><tr><td><code>off</code></td><td>no agent: one ssh per remote command, as before</td></tr></tbody></table><p><code>ERRAND_WARM=0</code> starts every session anew, even with a <code>Preload</code>. And <code>-v</code> shows what goes where: every command errand starts, including those it hands to an agent. → <a href="./upkeep#when-something-breaks">When something breaks</a></p><p>The design, and why the local side decides while the agents only execute: <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0005-the-local-side-orchestrates-agents-execute.md" target="_blank" rel="noreferrer">ADR 0005</a>.</p>`,39)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
